// 由 scripts/gen-app-catalog.mjs 从 Web 的目录与标志生成（修订第 213 条），不要手工修改；运行 make app-catalog 重新生成。
// 标志图形取自 Simple Icons（CC0-1.0）与各网站自己的图标；商标归各自所有者，这里只用于标识对应的服务。
// ignore_for_file: lines_longer_than_80_chars
import 'dart:ui';

/// 单色标志：24×24 视图框内的 SVG 路径与品牌色
class GlyphIcon {
  /// 创建标志
  const GlyphIcon(this.path, this.color);
  /// SVG 路径数据
  final String path;
  /// 品牌色
  final Color color;
}

/// 图片标志：PNG（Base64）；fill 铺满方块，contain 居中放在 bg 色（默认白色）的方块中
class ImageLogo {
  /// 创建图片标志
  const ImageLogo(this.png, {this.fill = false, this.bg});
  /// PNG 的 Base64
  final String png;
  /// 是否铺满
  final bool fill;
  /// 背景色
  final Color? bg;
}

/// 订阅目录中的一项
class CatalogEntry {
  /// 创建目录项
  const CatalogEntry(this.name, this.category, this.color, {this.letter, this.icon, this.currency, this.dial, this.country, this.hot = false});
  /// 名称
  final String name;
  /// 类别
  final String category;
  /// 品牌色
  final Color color;
  /// 图标字（默认取名称的第一个字母或汉字）
  final String? letter;
  /// 标志键（默认与目录键相同）
  final String? icon;
  /// 默认币种
  final String? currency;
  /// SIM 卡的国家 / 地区区号，如 +86
  final String? dial;
  /// SIM 卡的国家 / 地区（两位代码，大写）
  final String? country;
  /// 常用（选择服务时排在前面）
  final bool hot;
}

/// 连通性测试的一个目标
class SiteTarget {
  /// 创建目标
  const SiteTarget(this.id, this.name, this.urls, this.color, {this.letter, this.icon});
  /// 标识
  final String id;
  /// 名称
  final String name;
  /// 测试地址：前一个连接失败时改测下一个
  final List<String> urls;
  /// 品牌色
  final Color color;
  /// 图标字
  final String? letter;
  /// 标志键
  final String? icon;
}

/// 连通性测试的一组目标
class SiteGroup {
  /// 创建分组
  const SiteGroup(this.key, this.name, this.flag, this.sites);
  /// 键
  final String key;
  /// 名称
  final String name;
  /// 国旗
  final String flag;
  /// 目标
  final List<SiteTarget> sites;
}

